proc pExtraPostExprBlock*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk15 and indClass(p) in {icEq}):
    checkInd p, {icEq}
    if (p.tok.kind in {tkDo}):
      pDoBlock(p, false)
    elif (p.tok.kind in {tkOf}):
      expect p, tkOf
      pExprList p
      wrap p, m0, "ranges"
      expect p, tkColon
      pStmt p
      wrap p, m0, "of"
    elif (p.tok.kind in {tkElif}):
      expect p, tkElif
      pExpr p
      expect p, tkColon
      pStmt p
      wrap p, m0, "elif"
    elif (p.tok.kind in {tkExcept}):
      expect p, tkExcept
      if (p.tok.kind in Tk2):
        let m158 = mark(p)
        let m159 = mark(p)
        pExpr p
        while (p.tok.kind in {tkComma}):
          pComma p
          pExpr p
        discardUnused m159
        discardUnused m158
      else:
        emitEmpty p
      expect p, tkColon
      pStmt p
      wrap p, m0, "except"
    elif (p.tok.kind in {tkFinally}):
      expect p, tkFinally
      expect p, tkColon
      pStmt p
      wrap p, m0, "fin"
    elif (p.tok.kind in {tkElse}):
      expect p, tkElse
      expect p, tkColon
      pStmt p
      wrap p, m0, "else"
    else:
      error p, "expected extraPostExprBlock"
  else:
    error p, "expected extraPostExprBlock"
  discardUnused m0

proc pPostExprBlocks*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in {tkColon, tkDo} and indClass(p) in {icNoInd}):
    checkInd p, {icNoInd}
    if (p.tok.kind in {tkDo}):
      pDoBlock(p, true)
      while (p.tok.kind in Tk15 and indClass(p) in {icEq}):
        let m160 = mark(p)
        pExtraPostExprBlock p
        discardUnused m160
    elif (p.tok.kind in {tkColon}):
      expect p, tkColon
      if (p.tok.kind in {tkComment} and indClass(p) in {icNoInd}):
        let m161 = mark(p)
        pTrailComment p
        discardUnused m161
      let m162 = mark(p)
      if (p.tok.kind in Tk15 and indClass(p) in {icEq}):
        pExtraPostExprBlock p
      elif (p.tok.kind in Tk21 and indClass(p) in {icGt}) or (p.tok.kind in Tk9):
        pStmt p
      else:
        error p, "expected alternative"
      discardUnused m162
      while (p.tok.kind in Tk15 and indClass(p) in {icEq}):
        let m163 = mark(p)
        pExtraPostExprBlock p
        discardUnused m163
    else:
      error p, "expected postExprBlocks"
