proc pComplexOrSimpleStmt*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk28):
    let m312 = mark(p)
    if (p.tok.kind in {tkIf}):
      pIfStmt p
    elif (p.tok.kind in {tkWhen}):
      pWhenStmt p
    elif (p.tok.kind in {tkWhile}):
      pWhileStmt p
    elif (p.tok.kind in {tkTry}):
      pTryStmt p
    elif (p.tok.kind in {tkFor}):
      pForStmt p
    elif (p.tok.kind in {tkBlock}):
      pBlockStmt p
    elif (p.tok.kind in {tkStatic}):
      pStaticStmt p
    elif (p.tok.kind in {tkDefer}):
      pDeferStmt p
    elif (p.tok.kind in {tkAsm}):
      pAsmStmt p
    elif (p.tok.kind in {tkBind}):
      pBindStmt p
    elif (p.tok.kind in {tkMixin}):
      pMixinStmt p
    elif (p.tok.kind in {tkCase}):
      pCaseStmt p
    else:
      error p, "expected alternative"
    discardUnused m312
  elif (p.tok.kind in {tkExcept}):
    expect p, tkExcept
    emitEmpty p
    pColcom p
    pStmt p
    wrap p, m0, "except"
  elif (p.tok.kind in {tkFinally}):
    expect p, tkFinally
    pColcom p
    pStmt p
    wrap p, m0, "fin"
  elif (p.tok.kind in {tkProc}):
    pushInfo p
    expect p, tkProc
    pRoutine(p, "proc")
    popInfo p
  elif (p.tok.kind in {tkMethod}):
    pushInfo p
    expect p, tkMethod
    pRoutine(p, "method")
    popInfo p
  elif (p.tok.kind in {tkFunc}):
    pushInfo p
    expect p, tkFunc
    pRoutine(p, "func")
    popInfo p
  elif (p.tok.kind in {tkIterator}):
    pushInfo p
    expect p, tkIterator
    pRoutine(p, "iterator")
    popInfo p
  elif (p.tok.kind in {tkMacro}):
    pushInfo p
    expect p, tkMacro
    pRoutine(p, "macro")
    popInfo p
  elif (p.tok.kind in {tkTemplate}):
    pushInfo p
    expect p, tkTemplate
    pRoutine(p, "template")
    popInfo p
  elif (p.tok.kind in {tkConverter}):
    pushInfo p
    expect p, tkConverter
    pRoutine(p, "converter")
    popInfo p
  elif (p.tok.kind in {tkType}):
    expect p, tkType
    if (p.tok.kind in {tkAccent, tkComment, tkSymbol} and indClass(p) in {icNoInd, icGt}):
      pSection_typeDef p
    elif (p.tok.kind in {tkParLe}):
      var at313 = m0.info
      expect p, tkParLe
      at313 = p.info
      pPrimary(p, pmTypeDesc)
      expect p, tkParRi
      wrapAt p, m0, "typeof", at313
      var prec314 = getPrecedence(p)
      while prec314 >= -1 and indClass(p) == icNoInd:
        let assoc314 = (if isRightAssoc(p): 0 else: 1)
        let opassoc314 = p.info
        insertLeafAt p, m0, p.tok.s
        getTok p
        pSimpleExpr(p, prec314 + assoc314, pmNormal)
        wrapAt p, m0, "infix", opassoc314
        prec314 = getPrecedence(p)
    else:
      error p, "expected complexOrSimpleStmt"
  elif (p.tok.kind in {tkConst}):
    pushSection p, "const"
    expect p, tkConst
    pSection_constant p
    popSection p
  elif (p.tok.kind in {tkLet}):
    pushSection p, "let"
    expect p, tkLet
    pSection_variable p
    popSection p
  elif (p.tok.kind in {tkVar}):
    pushSection p, "var"
    expect p, tkVar
    pSection_variable p
    popSection p
  elif (p.tok.kind in {tkUsing}):
    pushLastSection p
    expect p, tkUsing
    pSection_variable p
    popSection p
    wrap p, m0, "using"
  else:
    pSimpleStmt p
  discardUnused m0

proc pStmt*(p: var Parser) =
  let m0 = mark(p)
  if (p.tok.kind in Tk8 and indClass(p) in {icGt}):
    pushInd p
    pComplexOrSimpleStmt p
    while (p.tok.kind in Tk8 and indClass(p) in {icEq}) or (p.tok.kind in {tkSemiColon}):
      let m315 = mark(p)
      let m316 = mark(p)
      if (p.tok.kind in Tk8 and indClass(p) in {icEq}):
        checkInd p, {icEq}
        pComplexOrSimpleStmt p
      elif (p.tok.kind in {tkSemiColon}):
        expect p, tkSemiColon
        if (p.tok.kind in Tk8 and indClass(p) in {icNoInd, icEq}):
          let m317 = mark(p)
          pOptSameInd p
          pComplexOrSimpleStmt p
          discardUnused m317
      else:
        error p, "expected alternative"
      discardUnused m316
      discardUnused m315
    popInd p
    wrap p, m0, "stmts"
  elif ((p.tok.kind in Tk9 and indClass(p) in {icNoInd, icLt, icEq})) and inSemiStmtList(p):
    pNotInd p
    pSimpleStmt p
  elif (p.tok.kind in Tk9 and indClass(p) in {icNoInd, icLt, icEq}):
    pNotInd p
    let m318 = mark(p)
    pSimpleStmt p
    while (p.tok.kind in {tkSemiColon}):
      expect p, tkSemiColon
      pSimpleStmt p
    discardUnused m318
    wrap p, m0, "stmts"
  else:
    error p, "expected stmt"
  discardUnused m0

